"""Result normalization and summary helpers shared by CLI surfaces."""
from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from benching.analytics.analyze import normalize_runs
from benching.benchmark.runs import resolve_run, run_json


def summary_for(directory: Path) -> dict[str, Any] | None:
    """Read the dashboard summary generated by analytics."""
    try:
        value = json.loads((directory / "summary.json").read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    return value if isinstance(value, dict) else None


def load_result(run_ref: str = "latest", provider: str | None = None) -> tuple[Path, dict[str, Any] | None]:
    """Load a run's canonical artifacts without side effects.

    Read-only by design: viewing results never renormalizes or rewrites
    completed artifacts (a stale in-progress run keeps showing its last
    canonical summary). Use reanalyze_run for explicit regeneration.
    """
    if run_ref == "latest" and provider:
        from benching.benchmark.runs import all_run_dirs

        matches = [directory for directory in all_run_dirs() if str((run_json(directory) or {}).get("provider", "")) == provider]
        if not matches:
            raise SystemExit(f"no runs for provider {provider!r}")
        directory = matches[0]
    else:
        directory = resolve_run(run_ref)
    if not (directory / "raw.jsonl").is_file() and not (directory / "metrics.jsonl").is_file():
        raise SystemExit(f"no telemetry found in {directory}")
    return directory, summary_for(directory)


def ensure_normalized(run_ref: str = "latest", provider: str | None = None) -> tuple[Path, dict[str, Any] | None]:
    """Backward-compatible alias for load_result (read-only)."""
    return load_result(run_ref, provider=provider)


def reanalyze_run(directory: Path) -> dict[str, Any] | None:
    """Explicitly regenerate one run's metrics/summary from its evidence.

    The only sanctioned write path for existing run artifacts outside
    run execution itself. Uses the run's own tokenizer context and never
    writes a comparison artifact.
    """
    normalize_runs([directory], execution="sequential", write_comparison=False)
    return summary_for(directory)

